$:set -euo pipefail
if test -f README.md; then cat README.md >/dev/null; fi
cat AGENTS.md >/dev/null
gh api repos/BestNameYet/Terminals/issues/3 --jq .body >/dev/null
gh auth setup-git
git config user.name 'github-actions[bot]'
git config user.email '41898282+github-actions[bot]@users.noreply.github.com'
node <<'NODE'
"use strict";
const fs=require("fs"),assert=require("assert"),crypto=require("crypto");
const draftPath="Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-draft.json";
const encodedPath="Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-aliased-copy.json";
const referencePath="references/user-defined-scope-rule.json";
const mappingPath="references/instruction-wrapper-key-aliases.json";
const taskPath="Tasks/User Prompt Task Queue/user-prompt-task-1794193447.json";
const read=p=>JSON.parse(fs.readFileSync(p,"utf8"));
const write=(p,v,compact)=>fs.writeFileSync(p,JSON.stringify(v,null,compact?0:2)+"\n");
const draft=read(draftPath),ref=read(referencePath),priorEncoded=read(encodedPath),dictionary=read(mappingPath),task=read(taskPath);
assert(Array.isArray(draft)&&draft.length===3);
assert.deepStrictEqual(draft[1],ref,"Standalone scope reference differs from draft");
assert(draft[1].title&&typeof draft[1].applicability==="string");
assert(Array.isArray(ref.examples)&&ref.examples.length===10&&ref.model,"Scope reference incomplete");
assert(priorEncoded[0].alias_lookup_path===mappingPath,"Expected unaliased bootstrap path");
assert(task.status==="pending_revision");
const aliasByKeyOld=new Map(Object.entries(dictionary.alias_to_key).map(([alias,key])=>[key,alias]));
const count=new Map();
const revised=structuredClone(draft);
revised[1]={
  title:ref.title,
  applicability:ref.applicability,
  standalone_rule_path:referencePath
};
function visit(x){
 if(Array.isArray(x))return x.forEach(visit);
 if(x===null||typeof x!=="object")return;
 for(const [k,v]of Object.entries(x)){count.set(k,(count.get(k)||0)+1);visit(v);}
}
visit(revised);
const aliases={};
for(const [k,v]of count){
 const alias=aliasByKeyOld.get(k);
 assert(alias&&alias[0]===k[0]&&alias.length<=2,"Missing or invalid prior alias "+k);
 aliases[alias]=k;
}
assert(Object.keys(aliases).length===count.size);
const mapKey=new Map(Object.entries(aliases).map(([alias,key])=>[key,alias]));
function transform(x,lookup){
 if(Array.isArray(x))return x.map(v=>transform(v,lookup));
 if(x===null||typeof x!=="object")return x;
 const obj={};
 for(const [k,v]of Object.entries(x)){
   const n=lookup.get(k);assert(n,"Missing mapped key: "+k);
   obj[n]=transform(v,lookup);
 }
 return obj;
}
const encoded=transform(revised,mapKey);
encoded[0].alias_lookup_path=mappingPath;
function decode(x){
 if(Array.isArray(x))return x.map(decode);
 if(x===null||typeof x!=="object")return x;
 const out={};for(const [k,v]of Object.entries(x)){
  const original=k==="alias_lookup_path"?k:aliases[k];
  assert(original,"Unmapped alias "+k);out[original]=decode(v);
 }return out;
}
const unaliased=decode(encoded);
delete unaliased[0].alias_lookup_path;
assert.deepStrictEqual(unaliased,revised);
assert.deepStrictEqual(revised[0],draft[0]);
assert.deepStrictEqual(revised[2],draft[2]);
assert.deepStrictEqual(revised[1],{title:ref.title,applicability:ref.applicability,standalone_rule_path:referencePath});
dictionary.alias_to_key=aliases;
dictionary.original_key_count=count.size;
dictionary.total_key_count_including_lookup=count.size;
dictionary.aliases_with_one_character=Object.keys(aliases).filter(a=>a.length===1).length;
dictionary.aliases_with_two_characters=Object.keys(aliases).filter(a=>a.length===2).length;
dictionary.source_template_sha256=crypto.createHash("sha256").update(JSON.stringify(revised,null,2)+"\n").digest("hex");
task.task.amendments.push({
 purpose:"Use a compact scope rule descriptor within the account-instruction wrapper while maintaining the full previously accepted scope rule as an external standalone reference.",
 user_instruction_summary:"Create an abbreviated rule for the template that preserves its title and applicability, removes its other members, and adds a path to the standalone scope rule reference.",
 implementation:"Replace the outer index-1 scope rule object with exactly title, applicability, and standalone_rule_path. Keep the complete object, including model and all ten examples, unchanged at references/user-defined-scope-rule.json. Update the aliased wrapper and lossless alias lookup to match.",
 status:"Implemented as a revision draft; user acceptance not recorded."
});
task.task.deliverable="A wrapper draft whose outer index 1 is a scope-rule descriptor containing title, applicability and standalone_rule_path, and whose analytics entry points to its complete reference, with external structural and machine-dialect rule references and an equivalent aliased copy.";
save(draftPath,revised,false);
save(encodedPath,encoded,true);
save(mappingPath,dictionary,false);
save(taskPath,task,false);
const fromDisk=decode(read(encodedPath));delete fromDisk[0].alias_lookup_path;
assert.deepStrictEqual(fromDisk,read(draftPath));
assert.deepStrictEqual(read(referencePath),ref);
assert.deepStrictEqual(read(draftPath)[2],draft[2]);
assert.strictEqual(read(taskPath).status,"pending_revision");
console.log("SCOPE_DESCRIPTOR",JSON.stringify(revised[1]));
console.log("REFERENCE_INTACT",referencePath,ref.examples.length,"examples");
console.log("ALIAS_ROUNDTRIP",true);
console.log("ALIAS_COUNT",count.size);
console.log("DRAFT_CHARACTERS",fs.readFileSync(draftPath,"utf8").length);
console.log("ALIASED_CHARACTERS",fs.readFileSync(encodedPath,"utf8").length);
console.log("NO_REFERENCE_CHANGE",true);

NODE
git add -- 'Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-draft.json' 'Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-aliased-copy.json' 'Tasks/User Prompt Task Queue/user-prompt-task-1794193447.json' 'references/instruction-wrapper-key-aliases.json'
git diff --cached --check
git commit -m 'Condense scope rule to title applicability and standalone reference path'
for i in 1 2 3 4; do git fetch origin main -q; git rebase origin/main -q; if git push origin HEAD:main; then break; fi; test "$i" -lt 4; done
printf 'PUBLISHED_COMMIT ';git rev-parse HEAD
git show --stat --oneline HEAD
